import { afterAll, expect, test } from "bun:test";

const temporaryFiles: string[] = [];

async function run(input: unknown, args: string[] = ["plan"]): Promise<{ exitCode: number; stdout: string; stderr: string }> {
  const path = `/tmp/dependency-planner-${crypto.randomUUID()}.json`;
  temporaryFiles.push(path);
  await Bun.write(path, JSON.stringify(input));
  const process = Bun.spawn({
    cmd: ["bun", "run", "src/cli.ts", ...args, path],
    stdout: "pipe",
    stderr: "pipe",
  });
  return {
    exitCode: await process.exited,
    stdout: await new Response(process.stdout).text(),
    stderr: await new Response(process.stderr).text(),
  };
}

afterAll(async () => {
  await Promise.all(temporaryFiles.map((path) => Bun.file(path).delete()));
});

test("plans a graph with deterministic layers and critical-path tie breaking", async () => {
  const result = await run({
    tasks: [
      { id: "release", duration: 1, dependsOn: ["build", "docs"] },
      { id: "docs", duration: 2, dependsOn: ["lint"] },
      { id: "build", duration: 2, dependsOn: ["lint"] },
      { id: "lint", duration: 1 },
      { id: "zero", duration: 0 },
    ],
  });

  expect(result.exitCode).toBe(0);
  expect(JSON.parse(result.stdout)).toEqual({
    order: ["lint", "build", "docs", "release", "zero"],
    layers: [["lint", "zero"], ["build", "docs"], ["release"]],
    earliest: {
      lint: { start: 0, finish: 1 },
      build: { start: 1, finish: 3 },
      docs: { start: 1, finish: 3 },
      release: { start: 3, finish: 4 },
      zero: { start: 0, finish: 0 },
    },
    totalDuration: 4,
    criticalPath: ["lint", "build", "release"],
  });
});

test("supports an empty graph", async () => {
  const result = await run({ tasks: [] });
  expect(result.exitCode).toBe(0);
  expect(JSON.parse(result.stdout)).toEqual({
    order: [], layers: [], earliest: {}, totalDuration: 0, criticalPath: [],
  });
});

test("rejects invalid schemas and reports a deterministic concrete cycle", async () => {
  const invalid = await run({ tasks: [{ id: "a", duration: 1, dependsOn: ["missing"] }] });
  expect(invalid.exitCode).not.toBe(0);
  expect(invalid.stderr).toContain("unknown task 'missing'");

