    tasks: [
      { id: "c", duration: 1, dependsOn: ["a"] },
      { id: "b", duration: 1, dependsOn: ["c"] },
      { id: "a", duration: 1, dependsOn: ["b"] },
    ],
  });
  expect(cycle.exitCode).not.toBe(0);
  expect(cycle.stderr).toContain("a -> b -> c -> a");
});

