type TaskInput = {
  id: string;
  duration: number;
  dependsOn: string[];
};

type Schedule = {
  order: string[];
  layers: string[][];
  earliest: Record<string, { start: number; finish: number }>;
  totalDuration: number;
  criticalPath: string[];
};

function fail(message: string): never {
  throw new Error(message);
}

function isRecord(value: unknown): value is Record<string, unknown> {
  return typeof value === "object" && value !== null && !Array.isArray(value);
}

function validate(input: unknown): TaskInput[] {
  if (!isRecord(input) || !Array.isArray(input.tasks)) {
    fail("Invalid input: expected an object with a tasks array.");
  }

  const tasks: TaskInput[] = [];
  const ids = new Set<string>();
  for (let index = 0; index < input.tasks.length; index++) {
    const raw = input.tasks[index];
    const label = `tasks[${index}]`;
    if (!isRecord(raw)) fail(`Invalid input: ${label} must be an object.`);
    if (typeof raw.id !== "string" || raw.id.length === 0) {
      fail(`Invalid input: ${label}.id must be a non-empty string.`);
    }
    if (ids.has(raw.id)) fail(`Invalid input: duplicate task id '${raw.id}'.`);
    if (typeof raw.duration !== "number" || !Number.isFinite(raw.duration) || raw.duration < 0) {
      fail(`Invalid input: ${label}.duration must be a finite non-negative number.`);
    }
    const dependsOn = raw.dependsOn === undefined ? [] : raw.dependsOn;
    if (!Array.isArray(dependsOn) || dependsOn.some((id) => typeof id !== "string")) {
      fail(`Invalid input: ${label}.dependsOn must be an array of strings.`);
    }
    if (new Set(dependsOn).size !== dependsOn.length) {
      fail(`Invalid input: ${label}.dependsOn must not contain duplicates.`);
    }
    if (dependsOn.includes(raw.id)) {
      fail(`Invalid input: ${label}.dependsOn cannot contain the task itself.`);
    }
    ids.add(raw.id);
    tasks.push({ id: raw.id, duration: raw.duration, dependsOn: [...dependsOn] });
  }
  for (const task of tasks) {
    for (const dependency of task.dependsOn) {
      if (!ids.has(dependency)) {
        fail(`Invalid input: task '${task.id}' depends on unknown task '${dependency}'.`);
      }
    }
  }
  return tasks;
}

function findCycle(tasks: TaskInput[]): string[] | undefined {
  const byId = new Map(tasks.map((task) => [task.id, task]));
  const state = new Map<string, 0 | 1 | 2>();
  const stack: string[] = [];

  const visit = (id: string): string[] | undefined => {
    state.set(id, 1);
    stack.push(id);
    for (const dependency of [...byId.get(id)!.dependsOn].sort()) {
      if (state.get(dependency) === 1) {
        return [...stack.slice(stack.indexOf(dependency)), dependency];
      }
      if (state.get(dependency) !== 2) {
        const cycle = visit(dependency);
        if (cycle) return cycle;
      }
    }
    stack.pop();
    state.set(id, 2);
    return undefined;
  };

  for (const id of [...byId.keys()].sort()) {
    if (!state.has(id)) {
      const cycle = visit(id);
      if (cycle) return cycle;
    }
  }
  return undefined;
}

function comparePaths(left: string[], right: string[]): number {
  for (let index = 0; index < Math.min(left.length, right.length); index++) {
    if (left[index] !== right[index]) return left[index] < right[index] ? -1 : 1;
  }
  return left.length - right.length;
}

function plan(tasks: TaskInput[]): Schedule {
  const cycle = findCycle(tasks);
  if (cycle) fail(`Dependency cycle detected: ${cycle.join(" -> ")}`);

  const byId = new Map(tasks.map((task) => [task.id, task]));
  const children = new Map<string, string[]>(tasks.map((task) => [task.id, []]));
  const remaining = new Map<string, number>();
  for (const task of tasks) {
    remaining.set(task.id, task.dependsOn.length);
    for (const dependency of task.dependsOn) children.get(dependency)!.push(task.id);
  }
  for (const value of children.values()) value.sort();

  const ready = tasks.filter((task) => task.dependsOn.length === 0).map((task) => task.id).sort();
  const order: string[] = [];
  while (ready.length > 0) {
    const id = ready.shift()!;
    order.push(id);
    for (const child of children.get(id)!) {
      const count = remaining.get(child)! - 1;
      remaining.set(child, count);
      if (count === 0) {
        ready.push(child);
        ready.sort();
      }
    }
  }

  const earliest: Schedule["earliest"] = {};
  const paths = new Map<string, string[]>();
  const layerById = new Map<string, number>();
  const layers: string[][] = [];
  for (const id of order) {
    const task = byId.get(id)!;
    let start = 0;
    let layer = 0;
    let bestPath = [id];
    for (const dependency of task.dependsOn) {
      const finish = earliest[dependency].finish;
      const candidatePath = [...paths.get(dependency)!, id];
      if (finish > start || (finish === start && comparePaths(candidatePath, bestPath) < 0)) {
        start = finish;
        bestPath = candidatePath;
      }
      layer = Math.max(layer, layerById.get(dependency)! + 1);
    }
    earliest[id] = { start, finish: start + task.duration };
    paths.set(id, bestPath);
    layerById.set(id, layer);
    (layers[layer] ??= []).push(id);
  }
  for (const layer of layers) layer.sort();

  let totalDuration = 0;
  let criticalPath: string[] = [];
  for (const id of order) {
    const finish = earliest[id].finish;
    const path = paths.get(id)!;
    if (finish > totalDuration || (finish === totalDuration && comparePaths(path, criticalPath) < 0)) {
      totalDuration = finish;
      criticalPath = path;
    }
  }
  return { order, layers, earliest, totalDuration, criticalPath };
}

async function main(args: string[]): Promise<void> {
  if (args.length !== 2 || args[0] !== "plan") {
    fail("Usage: bun run src/cli.ts plan INPUT.json");
  }
  let parsed: unknown;
  try {
    parsed = JSON.parse(await Bun.file(args[1]).text());
  } catch (error) {
    fail(`Unable to read valid JSON from '${args[1]}': ${error instanceof Error ? error.message : String(error)}`);
  }
  console.log(JSON.stringify(plan(validate(parsed))));
}

